<?php if ( ! defined( 'ABSPATH' ) ) { exit; } $group = $args['group']; ?><section id="activity" class="sd-panel sd-group-activity"><h2><?php esc_html_e( 'Community activity', 'social-discovery' ); ?></h2><?php if ( function_exists( 'bp_activity_get' ) ) : $activities = bp_activity_get( array( 'object' => 'groups', 'primary_id' => $group->id, 'per_page' => 10, 'page' => 1, 'display_comments' => false, 'show_hidden' => false ) ); if ( ! empty( $activities['activities'] ) ) : foreach ( $activities['activities'] as $activity ) : ?><article class="sd-group-activity-item"><strong><?php echo esc_html( sd_social_activity_author( $activity ) ); ?></strong><time><?php echo esc_html( $activity->date_recorded ); ?></time><div><?php echo wp_kses_post( wpautop( $activity->content ) ); ?></div></article><?php endforeach; else : ?><p class="sd-muted"><?php esc_html_e( 'No activity in this community yet.', 'social-discovery' ); ?></p><?php endif; else : ?><p class="sd-muted"><?php esc_html_e( 'Group activity is available when BuddyPress Activity is active.', 'social-discovery' ); ?></p><?php endif; ?></section>
